import{_ as i,a0 as p,w as s,s as d,I as l,x as a,a1 as r,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"發展中國家面臨的三個關鍵開源挑戰 | LCTT x X-CMD","titleTemplate":false,"description":"發展中國家面臨的三個關鍵開源挑戰 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"發展中國家面臨的三個關鍵開源挑戰 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"發展中國家面臨的三個關鍵開源挑戰 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230427.2 ⭐️⭐️ 3 key open source challenges in developing countries","title":"發展中國家面臨的三個關鍵開源挑戰","tag":"202307","desc":""},"relativePath":"202307/20230427.2 ⭐️⭐️ 3 key open source challenges in developing countries.md","filePath":"[post].md"}'),u={name:"202307/20230427.2 ⭐️⭐️ 3 key open source challenges in developing countries.md"};function h(m,e,f,b,x,T){const t=p("Link");return s(),d("div",null,[e[22]||(e[22]=l("h1",{id:"發展中國家面臨的三個關鍵開源挑戰",tabindex:"-1"},[a("發展中國家面臨的三個關鍵開源挑戰 "),l("a",{class:"header-anchor",href:"#發展中國家面臨的三個關鍵開源挑戰","aria-label":"Permalink to “發展中國家面臨的三個關鍵開源挑戰”"},"​")],-1)),e[23]||(e[23]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202307/27/073634a244fon440y25kug.jpg",alt:""})],-1)),e[24]||(e[24]=l("blockquote",null,[l("p",null,"開源在發展中國家面臨着許多困難，這些困難使人們對開源的看法以及與開源的聯繫變得不準確、不貼切。")],-1)),e[25]||(e[25]=l("blockquote",null,[l("p",null,"編者按：本文作者 Ahmed Sobeh 是 Aiven 開源項目辦公室的開源工程經理。他來自埃及，在開源領域有各種經驗。本文是他對埃及的開源文化的見解。")],-1)),l("p",null,[e[2]||(e[2]=a("當我回國，和科技行業或其他行業的人談起我的工作和我每天參與的話題時，我通常會對 ",-1)),l("ruby",null,[r(t,{href:"https://opensource.com/article/20/5/open-source-program-office"},{default:n(()=>[...e[0]||(e[0]=[a("開源計劃辦公室",-1)])]),_:1}),e[1]||(e[1]=l("rt",null,"Open Source Programs Office",-1))]),e[3]||(e[3]=a("（OSPO）這個想法感到困惑。一家公司在沒有明顯的直接經濟利益的情況下為開源項目做出貢獻，這種概念在文化上很難理解或解釋。",-1))]),e[26]||(e[26]=o('<p>作為一個在發展中國家出生併成長的人，我理解並贊同這個觀點。曾幾何時，我對開源軟件的唯一理解是，它是一種無需付費、無需等待特定問題或附加功能發佈即可使用的軟件。我可以自己在本地做任何我需要的事情。</p><p>在發展中國家，開源面臨着許多困難，這些困難使人們對它的看法和相關印象變得不準確和脱節。我將在本文中討論這些問題。</p><h3 id="發展中國家的開源挑戰" tabindex="-1">發展中國家的開源挑戰 <a class="header-anchor" href="#發展中國家的開源挑戰" aria-label="Permalink to “發展中國家的開源挑戰”">​</a></h3><p>開源在這些地區面臨的挑戰主要分為三個部分：</p><ul><li>社會與文化</li><li>資源與基礎設施</li><li>政府管理</li></ul><h3 id="社會與文化" tabindex="-1">社會與文化 <a class="header-anchor" href="#社會與文化" aria-label="Permalink to “社會與文化”">​</a></h3><p>眾所周知，科技中的文化，特別是其中的開源部分，源自它所存在的社會文化。這就是為什麼在當今世界，開源更有可能在世界較發達地區得到維持和維護。</p><p>但是，試想一個完美的社會，一個最適合開源發展、維持和維護的社會。這個社會的文化是什麼樣的？其主要特徵是什麼？</p><h4 id="開放和透明" tabindex="-1">開放和透明 <a class="header-anchor" href="#開放和透明" aria-label="Permalink to “開放和透明”">​</a></h4><p>開源想要發展，社會文化必須儘可能開放和透明。信息必須可以自由公開地獲取，這在許多欠發達地區是一個巨大的問題。信息往往受到繁文縟節的制約，普通公民難以獲取，更不用説那些試圖為開源做出貢獻的人了。</p><h4 id="自由" tabindex="-1">自由 <a class="header-anchor" href="#自由" aria-label="Permalink to “自由”">​</a></h4><p>“自由”這個詞有許多不同的含義與解釋。有言論自由、表達自由、選擇自由、信仰自由、宗教自由等等。在本文中，我最關心的自由方面是在沒有更高層機構干預的情況下建立新社區和組織的能力。這是開源的本質。分佈式協作模式是一種高效的協作模式，在這種模式下，大型團體在沒有強大的中央權威指揮的情況下開展合作。這是大多數這些地區面臨的另一個重大挑戰。新的社區和組織往往會受到質疑、密切監視，不幸的是，在某些情況下，甚至會因為害怕可能出現的新思想或其他原因而遭到起訴並最終被關閉。</p><h4 id="充滿活力" tabindex="-1">充滿活力 <a class="header-anchor" href="#充滿活力" aria-label="Permalink to “充滿活力”">​</a></h4><p>充滿活力的文化對開源的發展至關重要。準備接受和實行新想法的文化是發展開源最理想的地方。抵制改變和傾向於固守傳統方法會阻止社會接受新的技術和方法，這是大部分發展中國家中的主要問題。</p><p>這些地區抵制改變背後最重要也是最常見的原因是對未知的恐懼。把對未知的恐懼作為“發展中國家”的問題來討論是不公平的。這是在哪裏都常見問題，甚至在發達國家。但是恐懼背後的一些原因是發展中國家特有的。主要原因有兩個，一是對科技行業的能力缺乏信心，二是缺乏責任感。企業和個人都不信任現有軟件解決方案的功能，更不用説開源解決方案了。有一種觀點認為，開源軟件不安全、不可靠。當人們不相信軟件開發者的能力時這種擔憂會被放大。其次，人們不相信該系統會對使用軟件或法律衝突中可能出現的錯誤或問題追究責任。</p><h3 id="資源、基礎設施和經濟" tabindex="-1">資源、基礎設施和經濟 <a class="header-anchor" href="#資源、基礎設施和經濟" aria-label="Permalink to “資源、基礎設施和經濟”">​</a></h3><p>經濟挑戰是發展中國家開源面臨的最明顯的困難，影響着這些地區的開源開發者和社區。</p><h4 id="供應和資金" tabindex="-1">供應和資金 <a class="header-anchor" href="#供應和資金" aria-label="Permalink to “供應和資金”">​</a></h4><p>開源開發人員在發展中國家努力解決供應問題。無論是上網還是使用設備，當你每天都在努力獲取資源時，就很難成為一名固定的開源貢獻者。這些國家的數字鴻溝十分巨大。依然有許多地區沒有正常、穩定和高速的互聯網連接。在設備方面，這些地區也與世界其他地區存在市場差距。沒有足夠的資金購買最新、最強大的機器始終是個難題，但同時也存在供應問題。在這些地區，建立和運行最大的開源項目所需的現代化、功能強大的技術設備並不總能提供。</p><p>這些問題使得自我教育和學習具有挑戰性。由於這些供應問題，開源開發人員很難選擇一個開源項目，自行學習所有相關知識，並開始為其做出貢獻。</p><p>在這種情況下，如何建立開源社區呢？項目最終只能由少數擁有穩定高速互聯網連接和最新設備的特權人士來維護。剩下的將是零星的、偶爾來自他人的貢獻，很難被視為一個社區。一旦出現有償工作的機會，即使是這些人也會消失。我親眼見過多次這種情況。有人會開始瞭解一個開源項目，研究特定的堆棧或提高自己的技能，並開始為其做出貢獻。但一旦出現了有償工作的機會，即使是作為第二份工作，他們也會完全放棄開源項目。這是有道理的。任何個人都必須優先考慮自己和家人的生存手段。</p><p>這種資源匱乏和對少數特權人羣的依賴，也使其幾乎不可能為營銷活動、社區建設活動以及最後但並非最不重要的文獻本地化嘗試提供資金。</p><h4 id="本地化" tabindex="-1">本地化 <a class="header-anchor" href="#本地化" aria-label="Permalink to “本地化”">​</a></h4>',23)),l("p",null,[e[5]||(e[5]=a("英語是互聯網語言，但對許多國家來説並非如此。雖然幾乎所有的開發人員都會説基本的英語，但並不是每個人都有能力理解文檔、架構資源和技術規範，使他們能夠有意義地 ",-1)),r(t,{href:"https://opensource.com/article/22/3/contribute-open-source-2022"},{default:n(()=>[...e[4]||(e[4]=[a("為開源項目做出貢獻",-1)])]),_:1}),e[6]||(e[6]=a("。由於沒有相應的文檔，發展中國家的開發人員很難找到進入開源項目的切入點。為此所需的時間和資源通常會使這些地區的潛在貢獻者望而卻步。",-1))]),e[27]||(e[27]=o('<h4 id="員工合同" tabindex="-1">員工合同 <a class="header-anchor" href="#員工合同" aria-label="Permalink to “員工合同”">​</a></h4><p>幾乎所有的軟件員工合同都旨在將開發人員的每一行代碼、貢獻或想法貨幣化。任何參與外部項目的行為都會受到僱傭公司的質疑，而僱傭公司往往會阻止開發人員為開源做貢獻，以避免法律問題。法律偏向於公司和組織，阻止軟件開發人員做出外部貢獻。</p><h4 id="知識產權法" tabindex="-1">知識產權法 <a class="header-anchor" href="#知識產權法" aria-label="Permalink to “知識產權法”">​</a></h4><p>發展中國家的法律框架往往不具備處理知識產權和開源許可細微差別的能力。與發達國家相比，發展中國家的知識產權法律可能較弱或不夠全面，執法效力也可能較低。這可能使創作者和貢獻者難以保護自己的作品，並防止他人在未經許可的情況下使用。</p><p>此外，開源許可證可能很複雜。許多發展中國家可能不具備有效駕馭這些許可的法律專業知識或資源。這可能使開發人員很難在不無意中違反許可證條款的情況下為開源項目做出貢獻。</p><p>另一個問題是，知識產權法和開源許可證有時被視為發展中國家創新和發展的障礙。批評者認為，這些法律和許可會扼殺創造力，阻礙知識和技術的傳播，尤其是在資源和技術有限的地區。</p><p>總體而言，發展中國家圍繞知識產權法和開源貢獻所面臨的挑戰是複雜的、多方面的，需要採取細緻入微的方法來應對這些國家所面臨的獨特情況和挑戰。</p><h3 id="專有軟件交易" tabindex="-1">專有軟件交易 <a class="header-anchor" href="#專有軟件交易" aria-label="Permalink to “專有軟件交易”">​</a></h3><p>美國和歐洲的科技巨頭與發展中地區的政府簽訂了價值數十億美元、長達數十年的軟件供應協議。一旦有人當選，並決定開始採用開源軟件，他們就會發現擺脱這些交易需要付出巨大的代價。</p><h3 id="開源並非一帆風順" tabindex="-1">開源並非一帆風順 <a class="header-anchor" href="#開源並非一帆風順" aria-label="Permalink to “開源並非一帆風順”">​</a></h3><p>這些只是開放源代碼在發展中國家面臨的一些困難。要改善這種狀況，使開源技術的採用和發展變得可行，還有許多工作要做。在今後的文章中，我將深入探討具體的解決方案，但現在，我想説的是，任何事情都要從個人做起。當我們每個人都 “眾包” 開放文化時，我們生活和工作所在地區的文化也會隨之改變。盡你所能，將開放源代碼帶入你的社區，看看它會帶來什麼。</p><p><em>（題圖：MJ/e9f5a8be-b0bd-425a-8199-248f5c0abe16）</em></p><hr>',13)),l("p",null,[e[8]||(e[8]=a("via: ",-1)),r(t,{href:"https://opensource.com/article/23/4/challenges-open-source-developing-countries"},{default:n(()=>[...e[7]||(e[7]=[a("https://opensource.com/article/23/4/challenges-open-source-developing-countries",-1)])]),_:1})]),l("p",null,[e[13]||(e[13]=a("作者：",-1)),r(t,{href:"https://opensource.com/users/ahmed-sobeh"},{default:n(()=>[...e[9]||(e[9]=[a("Ahmed Sobeh",-1)])]),_:1}),e[14]||(e[14]=a(" 選題：",-1)),r(t,{href:"https://github.com/lkxed/"},{default:n(()=>[...e[10]||(e[10]=[a("lkxed",-1)])]),_:1}),e[15]||(e[15]=a(" 譯者：",-1)),r(t,{href:"https://github.com/wcjjdlhws"},{default:n(()=>[...e[11]||(e[11]=[a("wcjjdlhws",-1)])]),_:1}),e[16]||(e[16]=a(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[12]||(e[12]=[a("wxy",-1)])]),_:1})]),l("p",null,[e[19]||(e[19]=a("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[17]||(e[17]=[a("LCTT",-1)])]),_:1}),e[20]||(e[20]=a(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:n(()=>[...e[18]||(e[18]=[a("Linux中國",-1)])]),_:1}),e[21]||(e[21]=a(" 榮譽推出",-1))])])}const C=i(u,[["render",h]]);export{P as __pageData,C as default};
